def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, 18.0))

    slots = supply / float(WATER_REQ)
    scarcity = slots < 2.0

    prev_bids = []
    urgent_prev_bids = []
    max_prev = 0.0
    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            b = float(bid)
            prev_bids.append(b)
            if b > max_prev:
                max_prev = b
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_prev_bids.append(b)

    pressure_bid = max_prev
    if urgent_prev_bids:
        ub = max(urgent_prev_bids)
        if ub > pressure_bid:
            pressure_bid = ub

    if hp <= 2 or no_water >= 2:
        bid = max(62.0, pressure_bid + 2.0)
    elif hp <= 4 or no_water >= 1:
        bid = max(48.0, pressure_bid + 1.0 if pressure_bid > 0 else 48.0)
    else:
        if scarcity:
            if pressure_bid >= 100.0:
                bid = 34.0
            elif pressure_bid >= 75.0:
                bid = 42.0
            elif pressure_bid >= 45.0:
                bid = pressure_bid + 1.5
            else:
                bid = 39.0
        else:
            if pressure_bid >= 100.0:
                bid = 22.0
            elif pressure_bid >= 70.0:
                bid = 28.0
            elif pressure_bid >= 40.0:
                bid = 31.0
            else:
                bid = 24.0

    remaining_days = max(1, 10 - int(day) + 1)
    reserve_target = DAILY_SALARY * 0.45 * remaining_days
    max_affordable = budget
    if budget > reserve_target:
        max_affordable = max(0.0, budget - reserve_target * 0.35)
    else:
        max_affordable = max(0.0, budget * 0.75)

    if hp <= 2 or no_water >= 2:
        max_affordable = budget

    final_bid = min(float(budget), float(max_affordable), float(bid))
    if final_bid < 0.0:
        final_bid = 0.0
    return float(final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents (current)
    alive_opps = [o for o in opponents_status.values() if o.get('alive')]
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday traces to infer who is under pressure
    low_hp_opps = []
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        prev_bid = prev.get('bid', None)
        if prev_bid is not None:
            try:
                yesterday_bids.append(float(prev_bid))
            except Exception:
                pass
        prev_hp_after = prev.get('hp_after', None)
        if prev_hp_after is not None:
            try:
                if float(prev_hp_after) <= 3:
                    low_hp_opps.append(opp)
            except Exception:
                pass

    # Baseline: aim to cover requirement with some margin.
    # Supply is 15..25, so water units are supply/WATER_REQ-ish; we bid in money.
    # Use a conservative bid that still competes.
    bid_floor = DAILY_SALARY * 0.45
    bid_cap = DAILY_SALARY * 0.95

    # Pressure-based adjustment: if multiple opponents ended yesterday with low hp, they may continue overbidding.
    pressure = len(low_hp_opps)

    # Use yesterday max bid as a proxy for market intensity.
    market = max(yesterday_bids) if yesterday_bids else bid_floor

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # If I'm in danger, bid harder.
    if my_hp <= 2.0:
        target = max(market * 0.85, DAILY_SALARY * 0.75)
    elif my_hp <= 4.0:
        target = max(market * 0.7, DAILY_SALARY * 0.6)
    else:
        # Healthy: bid based on pressure and market.
        if pressure >= 2:
            target = max(market * 0.65, bid_floor * 1.05)
        elif pressure == 1:
            target = max(market * 0.55, bid_floor)
        else:
            target = max(market * 0.45, bid_floor * 0.95)

    # Supply-aware tweak: with higher supply, we can bid less.
    if supply >= 21.0:
        target *= 0.92
    elif supply <= 17.0:
        target *= 1.05

    # Ensure within budget and caps.
    target = min(target, bid_cap)
    target = min(target, my_budget)

    # If budget is too low, still bid something meaningful but not all-in.
    if my_budget < DAILY_SALARY * 0.5:
        target = min(target, my_budget * 0.75)

    # Final clamp
    if target < 0:
        target = 0.0

    return float(target)

